mapper.update:
UPDATE resources
title = #{title}, description = #{description}, course = #{course}, file_id = #{fileId}, status = #{status}, reject_reason = #{rejectReason},
WHERE id = #{id}

mapper.select:
SELECT * FROM resources

     AND created_at >= #{begin}
     AND created_at <= #{end}
     AND status = #{status}
     AND (status = 1 OR user_id = #{userId})

ORDER BY created_at DESC
